/* Langfuse Teaching — Shared Stylesheet */
/* Tufte-inspired: clean, readable, print-friendly */

:root {
  --text: #1a1a1a;
  --background: #fafaf9;
  --accent: #2563eb;
  --accent-light: #dbeafe;
  --muted: #6b7280;
  --border: #e5e7eb;
  --code-bg: #f3f4f6;
  --success: #16a34a;
  --warning: #d97706;
  --font: 'Georgia', 'Times New Roman', serif;
  --font-mono: 'SFMono-Regular', 'Consolas', 'Liberation Mono', monospace;
  --measure: 65ch;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  color: var(--text);
  background: var(--background);
  line-height: 1.7;
  padding: 2rem 1.5rem;
  font-size: 1.05rem;
}

@media (min-width: 720px) {
  body { padding: 3rem 2rem; }
}

article {
  max-width: var(--measure);
  margin: 0 auto;
}

/* Headings */
h1 {
  font-size: 2.2rem;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.25rem;
  letter-spacing: -0.01em;
}

h2 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-top: 2.5rem;
  margin-bottom: 0.75rem;
  line-height: 1.3;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.3rem;
}

h3 {
  font-size: 1.15rem;
  font-weight: 600;
  margin-top: 1.75rem;
  margin-bottom: 0.5rem;
}

/* Metadata */
.lesson-meta {
  color: var(--muted);
  font-size: 0.85rem;
  margin-bottom: 2rem;
  font-family: var(--font-mono);
}

/* Paragraphs */
p { margin-bottom: 1rem; }

/* Links */
a {
  color: var(--accent);
  text-decoration: none;
}
a:hover { text-decoration: underline; }

/* Code */
code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--code-bg);
  padding: 0.15em 0.4em;
  border-radius: 3px;
}

pre {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  background: var(--code-bg);
  padding: 1rem;
  border-radius: 6px;
  overflow-x: auto;
  margin-bottom: 1rem;
  line-height: 1.5;
  border: 1px solid var(--border);
}

/* Blockquotes for callouts */
blockquote {
  border-left: 4px solid var(--accent);
  padding: 0.75rem 1rem;
  margin: 1rem 0;
  background: var(--accent-light);
  border-radius: 0 6px 6px 0;
}

blockquote strong:first-child {
  display: block;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent);
  margin-bottom: 0.25rem;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
  font-size: 0.9rem;
}

th, td {
  text-align: left;
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--border);
}

th {
  font-weight: 600;
  background: var(--code-bg);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Lists */
ul, ol { margin-bottom: 1rem; padding-left: 1.5rem; }
li { margin-bottom: 0.25rem; }

/* Dividers */
hr {
  border: none;
  border-top: 1px solid var(--border);
  margin: 2rem 0;
}

/* Sidenote-like callouts */
.sidenote {
  font-size: 0.85rem;
  color: var(--muted);
  border-left: 2px solid var(--muted);
  padding-left: 0.75rem;
  margin: 0.75rem 0;
}

/* Exercise box */
.exercise {
  border: 2px solid var(--success);
  border-radius: 8px;
  padding: 1.25rem;
  margin: 1.5rem 0;
  background: #f0fdf4;
}

.exercise h3 {
  margin-top: 0;
  color: var(--success);
}

/* Next lesson link */
.next-lesson {
  display: block;
  text-align: center;
  margin-top: 3rem;
  padding: 1rem;
  border: 2px solid var(--accent);
  border-radius: 8px;
  font-weight: 600;
  font-size: 1.1rem;
}

/* Print */
@media print {
  body { padding: 0; font-size: 11pt; }
  a { color: inherit; }
  pre { white-space: pre-wrap; }
