import csv, sys, re, json
csv.field_size_limit(sys.maxsize)

def extract_user_message(raw):
    """Find the last user-role message content in a JSON message array string."""
    try:
        # Unescape once (the stored string is JSON-escaped)
        # The outer string is a JSON array; the content is double-escaped
        # Try progressive unescape
        for attempt in range(3):
            try:
                parsed = json.loads(raw)
                break
            except Exception:
                raw = raw.replace('\\\\', '\\').replace('\\"', '"').replace('\\n', '\n')
        else:
            parsed = None
        if isinstance(parsed, list):
            user_msgs = [m.get('content') for m in parsed if isinstance(m, dict) and m.get('role') == 'user']
            # prefer last user message (the actual prompt)
            if not user_msgs:
                user_msgs = [m.get('content') for m in parsed if isinstance(m, dict) and m.get('content')]
            for c in reversed(user_msgs):
                if isinstance(c, str) and c.strip():
                    return c.strip()[:90]
        elif isinstance(parsed, dict) and 'content' in parsed:
            return str(parsed['content'])[:90]
        elif isinstance(parsed, str):
            return parsed[:90]
    except Exception as e:
        pass
    return None

rows = []
with open('trace_inputs.tsv', encoding='utf-8', errors='replace') as f:
    reader = csv.reader(f, delimiter='\t')
    for line in reader:
        if not line or len(line) < 6:
            continue
        trace_id, ts, raw, project, env, et = line[0], line[1], line[2], line[3], line[4], line[5]
        name = extract_user_message(raw) or 'untitled'
        rows.append((trace_id, ts, name.replace('\t', ' ').replace('\n', ' '), project, env, et))

print(f"Total: {len(rows)}, named: {sum(1 for r in rows if r[2] != 'untitled')}")
